typedef pair<ll,ll> pair_ll;
const int MAX_SIZE=200017;
unordered_map<ll,ll> cache_map;
ll count_digits_ll(ll x){
  ll cnt=0;
  while(x){
    cnt++;
    x/=10;
  }
  return cnt;
}
ll reverse_number(ll x){
  ll digits[17],pos=0;
  while(x){
    digits[pos++]=(x%10)-(x<0?-1:1);
    x/=10;
  }
  ll res=0;
  while(pos--){
    res=res*10+digits[pos];
  }
  return res;
}
ll previous_value_ll(ll x){
  ll c=0,orig=x;
  while(x){
    c*=10;
    c+=(x<0?-1:1);
    x/=10;
  }
  c*=10;
  c++;
  return orig - c;
}
ll last_digit_ll(ll x){
  while(x>=10)
    x/=10;
  return x;
}
ll delete_leading_ll(ll x){
  ll digits[17],p=0;
  while(x>=10){
    digits[p++]=x%10;
    x/=10;
  }
  ll res=0;
  while(p--){
    res=res*10+digits[p];
  }
  return res;
}
ll compute_value(ll x){
  if(x<=11)return min(13 - x, x);
  if(cache_map[x])return cache_map[x];
  ll n=0,t=1;
  while(t<x){
    t*=10;
    t++;
    n++;
  }
  if(x*2>=t)
    return cache_map[x]=min(compute_value(t - x)+n+1, (x/(t/10))*n+compute_value(x%(t/10)));
  return cache_map[x]=(x/(t/10))*n+compute_value(x%(t/10));
}

